export const e2 = () => 1;

type Units = "metric" | "imperial";
const api = "https://api.example.com";
/** Get the current weather for a city. */
export const weather = (
  /** The city name, such as "Paris". */
  city: string,
  /** Temperature units. */
  units: Units = "metric",
) => {
  const r = http.get(`${api}/weather`, {params: {q: city, units}});
  {city, temp: r.body.temp, summary: r.body.summary}
};

type Order = {id: string, total: float, vip: bool};
const priority = (o: Order) => o.vip || o.total > 500;
export const onOrder = (order: Order) => ({
  queue: priority(order) ? "fast" : "standard",
  notify: order.vip,
});
